EXCEPTION
    WHEN e_rejets THEN
        FOR j IN 1 .. SQL%BULK_EXCEPTIONS.COUNT LOOP
            DBMS_OUTPUT.PUT_LINE('REJET brut_usager, numero_ligne=' || (4000 + SQL%BULK_EXCEPTIONS(j).ERROR_INDEX)
                || ' : ' || SQLERRM(-SQL%BULK_EXCEPTIONS(j).ERROR_CODE));
        END LOOP;
        ROLLBACK;
        RAISE;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('ECHEC brut_usager, bloc 4001-4500 : ' || SQLERRM);
        ROLLBACK;
        RAISE;
END;
