    e_rejets EXCEPTION;
    PRAGMA EXCEPTION_INIT(e_rejets, -24381);
BEGIN
    SELECT id_lot INTO v_id_lot FROM lot_source WHERE libelle = 'CSV_G08_d3bd9e88655a55744388db29403dbdf157955fce17f85ca8ac9478e21d3ad1d4';
    FORALL i IN 1 .. 467 SAVE EXCEPTIONS
        INSERT INTO brut_usager (id_lot, numero_ligne, ligne_originale, id_adherent, nom, prenom, email, telephone, ville, id_salle, date_inscription)
        VALUES (v_id_lot, v_numeros(i), v_0(i), v_1(i), v_2(i), v_3(i), v_4(i), v_5(i), v_6(i), v_7(i), v_8(i));
    IF SQL%ROWCOUNT <> 467 THEN
        RAISE_APPLICATION_ERROR(-20003, 'Nombre de lignes insérées incorrect.');
    END IF;
EXCEPTION
    WHEN e_rejets THEN
        FOR j IN 1 .. SQL%BULK_EXCEPTIONS.COUNT LOOP
            DBMS_OUTPUT.PUT_LINE('REJET brut_usager, numero_ligne=' || (20000 + SQL%BULK_EXCEPTIONS(j).ERROR_INDEX)
                || ' : ' || SQLERRM(-SQL%BULK_EXCEPTIONS(j).ERROR_CODE));
        END LOOP;
        ROLLBACK;
        RAISE;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('ECHEC brut_usager, bloc 20001-20467 : ' || SQLERRM);
        ROLLBACK;
        RAISE;
END;
